import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, uv, mul } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  // Helper to safely get config values
  const position = config.position ?? [-1.25, 1.6, 0];
  const rotation = config.rotation ?? [0, 0, 0];
  const scale = config.scale ?? [1, 1, 1];

  const nodeGroup = new Group();
  nodeGroup.position.set(...position);
  nodeGroup.rotation.set(...rotation);
  nodeGroup.scale.set(...scale);

  // Geometry
  const geometry = new PlaneGeometry(1, 1, 64, 64);

  // Base material (placeholder until textures load)
  const material = new MeshStandardNodeMaterial({
    color: 0xffffff,
    roughness: 0.7,
    metalness: 0.0,
    transparent: true,
  });

  const mesh = new Mesh(geometry, material);
  nodeGroup.add(mesh);

  // Load textures asynchronously
  let colorTex = null;
  let depthTex = null;

  const disposables = [];

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      colorTex = tex;
      material.map = tex;
      material.needsUpdate = true;
      disposables.push(() => tex.dispose());
    });
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthTex = tex;
      // Build displacement node once depth texture is ready
      const dispNode = mul(texture(depthTex), 0.15); // subtle displacement strength
      material.displacementNode = dispNode;
      material.needsUpdate = true;
      disposables.push(() => tex.dispose());
    });
  }

  // Parallax effect primitive (if exists)
  const primitiveHandles = [];
  if (ctx.primitives && ctx.primitives['parallax-scroll']) {
    const ph = ctx.primitives['parallax-scroll'](nodeGroup, { intensity: 0.05 });
    primitiveHandles.push(ph);
  }

  // Interaction timelines
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(
    nodeGroup.position,
    {
      y: `+=0.15`,
      duration: 0.7,
      ease: 'power3.out',
    }
  );

  // Handlers
  const handlers = {
    hoverEnter: () => {
      hoverTimeline.play();
    },
    hoverLeave: () => {
      hoverTimeline.reverse();
    },
    click: () => {
      ctx.emit('hub-features.select');
    },
  };

  nodeGroup.userData.handlers = handlers;

  // Cleanup
  nodeGroup.userData.cleanup = () => {
    hoverTimeline.kill();
    primitiveHandles.forEach((h) => {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    });
    disposables.forEach((fn) => fn());
    geometry.dispose();
    material.dispose();
  };

  return nodeGroup;
}
